await page.getByText('Yes, I have pets',{exact:true}).click();
await page.locator('#next-btn').click();assert(await page.locator('#date-title').isVisible());await page.locator('#next-btn').click();assert(await page.locator('#date-error').textContent());
await page.locator('.day:not([disabled])').first().click();await page.getByText('9:00 am',{exact:true}).click();
await page.screenshot({path:'/tmp/tidy-run2-calendar.png',fullPage:true});
await page.locator('#next-btn').click();assert(await page.locator('#review-title').isVisible());assert((await page.locator('#review-details').textContent()).includes('Alex Morgan'));
await page.getByRole('button',{name:'Edit contact details',exact:true}).click();assert.equal(await page.locator('#firstName').inputValue(),'Alex');await page.locator('#firstName').fill('');await page.locator('[data-step=\"3\"]').click();assert(await page.locator('#contact-title').isVisible());await page.locator('#firstName').fill('Robin');await page.locator('[data-step=\"3\"]').click();assert(await page.locator('#review-title').isVisible());assert((await page.locator('#review-details').textContent()).includes('Robin Morgan'));
await page.locator('#next-btn').click();assert(await page.locator('#success-title').isVisible());await page.locator('#return-review').click();assert(await page.locator('#review-title').isVisible());
assert.deepEqual(errors,[]);console.log('PASS: responsive widths, required validation, counters, pets, date/time, retained inputs, review edits, forward validation, demo completion, no JS errors.');
await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
